import React, { useState } from "react";

const Login2 = () => {
    const [darkMode, setDarkMode] = useState(false);

    return (
        <div
            className={`min-h-screen flex items-center justify-center transition-colors duration-300 ${
                darkMode ? "bg-gray-900" : "bg-white"
            }`}
        >
            <button
                onClick={() => setDarkMode(!darkMode)}
                className={`absolute top-6 right-6 px-4 py-2 rounded-full shadow ${
                    darkMode
                        ? "bg-gray-800 text-white hover:bg-gray-700"
                        : "bg-gray-200 text-gray-900 hover:bg-gray-300"
                } transition`}
                aria-label="Toggle dark mode"
            >
                {darkMode ? "🌙" : "☀️"}
            </button>
            <form
                className={`w-full max-w-sm p-8 rounded-xl shadow-lg ${
                    darkMode ? "bg-gray-800" : "bg-white"
                }`}
            >
                <h2
                    className={`text-2xl font-bold mb-6 text-center ${
                        darkMode ? "text-white" : "text-gray-900"
                    }`}
                >
                    Login
                </h2>
                <div className="mb-4">
                    <label
                        className={`block mb-2 text-sm font-medium ${
                            darkMode ? "text-gray-300" : "text-gray-700"
                        }`}
                        htmlFor="email"
                    >
                        Email
                    </label>
                    <input
                        className={`w-full px-4 py-2 rounded-lg border focus:outline-none focus:ring-2 ${
                            darkMode
                                ? "bg-gray-700 border-gray-600 text-white focus:ring-blue-500"
                                : "bg-gray-100 border-gray-300 text-gray-900 focus:ring-blue-400"
                        }`}
                        type="email"
                        id="email"
                        placeholder="you@example.com"
                        required
                    />
                </div>
                <div className="mb-6">
                    <label
                        className={`block mb-2 text-sm font-medium ${
                            darkMode ? "text-gray-300" : "text-gray-700"
                        }`}
                        htmlFor="password"
                    >
                        Password
                    </label>
                    <input
                        className={`w-full px-4 my-2 py-2 rounded-lg border focus:outline-none focus:ring-2 ${
                            darkMode
                                ? "bg-gray-700 border-gray-600 text-white focus:ring-blue-500"
                                : "bg-gray-100 border-gray-300 text-gray-900 focus:ring-blue-400"
                        }`}
                        type="password"
                        id="password"
                        placeholder="••••••••"
                        required
                    />
                </div>
                <button
                    type="submit"
                    className={`w-full py-2 rounded-lg font-semibold transition ${
                        darkMode
                            ? "bg-blue-600 text-white hover:bg-blue-700"
                            : "bg-blue-500 text-white hover:bg-blue-600"
                    }`}
                >
                    Sign In
                </button>
                <div className="mt-4 text-center">
                    <a
                        href="#"
                        className={`text-sm underline ${
                            darkMode ? "text-gray-400 hover:text-white" : "text-gray-500 hover:text-gray-900"
                        }`}
                    >
                        Forgot password?
                    </a>
                </div>
            </form>
        </div>
    );
};

export default Login2;